#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <string>
#include <thread>
#include <vector>

#include <pagmo/algorithm.hpp>
#include <pagmo/algorithms/de.hpp>
#include <pagmo/archipelago.hpp>
#include <pagmo/problem.hpp>
#include <pagmo/problems/rosenbrock.hpp>

#include "provenance.hpp"

int main(int argc, char* argv[]) {
    // 1. Stress-test parameters scaled to saturate all hardware threads on isotope
    unsigned int hw_threads = std::thread::hardware_concurrency();
    unsigned int num_islands = (hw_threads > 0) ? hw_threads : 24;
    unsigned int dimensions = 50;
    unsigned int population_size = 100;
    unsigned int gens_per_step = 2500;
    unsigned int evolve_steps = 10; // 25,000 generations per island

    unsigned int algo_seed = 42;
    unsigned int archi_seed = 12345;

    double goal_fitness = 0.0;
    double max_allowed_fitness = 1.0e-5;
    double max_allowed_distance = 1.0e-2;

    std::string banner(80, '=');
    std::string divider(80, '-');

    std::cout << banner << "\n";
    std::cout << "STRESS BENCHMARK INTENT & EXPECTED OUTCOME\n";
    std::cout << banner << "\n";
    std::cout << "Goal: Minimize " << dimensions << "-D Rosenbrock function using "
              << num_islands << " islands (" << population_size << " individuals each)\n";
    std::cout << "      running Differential Evolution for "
              << (gens_per_step * evolve_steps) << " generations per island.\n";
    std::cout << "Pass: Fitness < " << max_allowed_fitness
              << " and distance from x* = [1, ..., 1] < " << max_allowed_distance << "\n";
    std::cout << "Seed: Algorithm base seed = " << algo_seed
              << ", Archipelago seed = " << archi_seed << "\n\n";

    // 2. Build problem, solver, and 24-island shared-memory archipelago
    pagmo::rosenbrock raw_problem(dimensions);
    pagmo::problem prob(raw_problem);

    // Disable early ftol/xtol stop (1e-12) so every island works the full generation budget
    pagmo::de raw_algorithm(gens_per_step, 0.8, 0.9, 2, 1e-12, 1e-12, algo_seed);
    pagmo::algorithm algo(raw_algorithm);

    pagmo::archipelago archi(num_islands, algo, prob, population_size, archi_seed);

    // 3. Launch all 24 threads and time wall-clock execution
    std::cout << "Launching " << num_islands << " island threads...\n";
    auto t_start = std::chrono::steady_clock::now();

    archi.evolve(evolve_steps);
    archi.wait_check();

    auto t_end = std::chrono::steady_clock::now();
    double elapsed_sec = std::chrono::duration<double>(t_end - t_start).count();
    std::cout << num_islands << " island threads completed in "
              << std::fixed << std::setprecision(3) << elapsed_sec << " s.\n\n";

    // 4. Print the results table (Measured vs. Goal)
    std::cout << banner << "\n";
    std::cout << "RESULTS SUMMARY (MEASURED VS. GOAL)\n";
    std::cout << banner << "\n";
    std::cout << std::left
              << std::setw(9)  << "Island"
              << std::setw(15) << "Measured_f"
              << std::setw(10) << "Goal_f"
              << std::setw(15) << "Diff (f-Goal)"
              << std::setw(15) << "||x - x*||_2"
              << std::setw(12) << "Fevals"
              << "Status\n";
    std::cout << divider << "\n";

    bool all_passed = true;
    unsigned long long total_fevals = 0;

    for (std::size_t i = 0; i < archi.size(); ++i) {
        pagmo::population pop = archi[i].get_population();
        std::vector<double> best_f = pop.champion_f();
        std::vector<double> best_x = pop.champion_x();

        double measured_f = best_f[0];
        double diff_f = measured_f - goal_fitness;
        unsigned long long fevals = pop.get_problem().get_fevals();
        total_fevals += fevals;

        double sum_of_squares = 0.0;
        for (std::size_t j = 0; j < best_x.size(); ++j) {
            double error = best_x[j] - 1.0;
            sum_of_squares += error * error;
        }
        double distance_to_optimum = std::sqrt(sum_of_squares);

        bool island_passed = (measured_f < max_allowed_fitness) && (distance_to_optimum < max_allowed_distance);
        if (!island_passed) {
            all_passed = false;
        }

        std::string status = island_passed ? "PASS" : "FAIL";

        std::cout << std::left << std::setw(9) << i
                  << std::scientific << std::setprecision(4)
                  << std::setw(15) << measured_f
                  << std::defaultfloat << std::setw(10) << goal_fitness
                  << std::scientific << std::showpos << std::setw(15) << diff_f << std::noshowpos
                  << std::setw(15) << distance_to_optimum
                  << std::defaultfloat << std::setw(12) << fevals
                  << status << "\n";
    }

    double mevals_per_sec = (static_cast<double>(total_fevals) / 1.0e6) / elapsed_sec;
    std::cout << divider << "\n";
    std::cout << "Total Fevals:         " << total_fevals
              << " (" << std::fixed << std::setprecision(2) << mevals_per_sec << " M evals/sec)\n";
    std::cout << "Wall-Clock Time:      " << std::fixed << std::setprecision(3) << elapsed_sec << " s\n";
    std::cout << "Overall Verification: " << (all_passed ? "SUCCESS" : "FAILURE") << "\n\n";

    telemetry::print_provenance(argc, argv);

    return all_passed ? 0 : 1;
}
